{
  "design": {
    "theme": "crayon",
    "picture_style": "illustration"
  },
  "flow": [
    {"slide":1,"does":"Recall equal sharing","look_at":{"kind":"picture","shows":"Two plates holding the same number of counters"},"teaches":[]},
    {"slide":2,"does":"Introduce the learning goals","look_at":{"kind":"none","shows":null},"teaches":[]},
    {"slide":3,"does":"Teach halves and quarters of shapes","look_at":{"kind":"diagram","shows":"One of two equal parts and one of four equal parts shaded"},"teaches":[1]},
    {"slide":4,"does":"Correct the unequal-parts misconception","look_at":{"kind":"picture","shows":"A rectangle cut into two unequal pieces"},"teaches":[1]},
    {"slide":5,"does":"Identify shaded fractions independently","look_at":{"kind":"diagram","shows":"Two shapes with different equal divisions"},"teaches":[1]},
    {"slide":6,"does":"Model finding half of an amount","look_at":{"kind":"diagram","shows":"Twelve counters shared into two equal groups"},"teaches":[2]},
    {"slide":7,"does":"Try finding half by equal sharing","look_at":{"kind":"diagram","shows":"Sixteen counters shared into two groups without counts"},"teaches":[2]},
    {"slide":8,"does":"Model finding a quarter of an amount","look_at":{"kind":"diagram","shows":"Twelve counters shared into four equal groups"},"teaches":[3]},
    {"slide":9,"does":"Try finding a quarter by equal sharing","look_at":{"kind":"diagram","shows":"Sixteen counters shared into four groups without counts"},"teaches":[3]},
    {"slide":10,"does":"Practise sharing independently","look_at":{"kind":"none","shows":null},"teaches":[2,3]},
    {"slide":11,"does":"Apply fractions to a new situation","look_at":{"kind":"none","shows":null},"teaches":[2,3]},
    {"slide":12,"does":"Check mixed understanding before the worksheet exit ticket","look_at":{"kind":"none","shows":null},"teaches":[1,2,3]}
  ],
  "title": {
    "template": "title",
    "heading": "Halves and quarters",
    "lead": "Look at the plates. What makes this sharing fair?",
    "picture": {
      "shows": "Two plates, each holding four identical counters",
      "must_see": ["two matching plates","four counters each"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Equal parts",
      "lead": "Equal parts are the same size.",
      "points": [
        {"label":"Half","text":"One of two equal parts."},
        {"label":"Quarter","text":"One of four equal parts."}
      ],
      "figure": {
        "kind": "fraction-shapes",
        "shows": "A half and a quarter of matching rectangles",
        "alt": "Two matching rectangles: one has one of two equal parts shaded; the other has one of four equal parts shaded.",
        "title": null,
        "shapes": [
          {"shape":"rectangle","parts":2,"cut":"vertical","shaded":1,"name":"half"},
          {"shape":"rectangle","parts":4,"cut":"grid","shaded":1,"name":"quarter"}
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Two pieces: always halves?",
      "lead": "These pieces are not halves.",
      "points": [
        {"label":"Check","text":"Halves must be equal in size."}
      ],
      "figure": {
        "shows": "A rectangle divided vertically into a narrow piece and a wide piece, with the narrow piece shaded",
        "must_see": ["one whole rectangle","two unequal pieces","narrow shaded piece"],
        "subject": "generic"
      }
    },
    {
      "template": "big-visual",
      "heading": "Name the shaded part",
      "lead": "Say half or quarter for each shape. Explain how you know.",
      "figure": {
        "kind": "fraction-shapes",
        "shows": "Two shaded shapes for pupils to identify",
        "alt": "Shape A is a square with one of four equal parts shaded. Shape B is a circle with one of two equal parts shaded.",
        "title": null,
        "shapes": [
          {"shape":"square","parts":4,"cut":"grid","shaded":1,"name":"A"},
          {"shape":"circle","parts":2,"cut":"auto","shaded":1,"name":"B"}
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Find half of 12",
      "lead": "Share 12 counters into two equal groups.",
      "points": [
        "Each group has 6 counters.",
        {"label":"Half","text":"Half of 12 is 6."}
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared equally into two groups",
        "alt": "Twelve counters in two equal groups of six.",
        "title": null,
        "total": 12,
        "groups": 2,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Find half of 16",
      "lead": "Count one group. Complete: Half of 16 is __.",
      "figure": {
        "kind": "equal-groups",
        "shows": "Sixteen counters shared into two equal groups for pupils to count",
        "alt": "Sixteen counters shared equally between two rings, with no group counts given.",
        "title": null,
        "total": 16,
        "groups": 2,
        "layout": "rings",
        "show_count": "none",
        "unknown": true
      }
    },
    {
      "template": "visual-text",
      "heading": "Find a quarter of 12",
      "lead": "Share 12 counters into four equal groups.",
      "points": [
        "Each group has 3 counters.",
        {"label":"Quarter","text":"A quarter of 12 is 3."}
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared equally into four groups",
        "alt": "Twelve counters in four equal groups of three.",
        "title": null,
        "total": 12,
        "groups": 4,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Find a quarter of 16",
      "lead": "Count one group. Complete: A quarter of 16 is __.",
      "figure": {
        "kind": "equal-groups",
        "shows": "Sixteen counters shared into four equal groups for pupils to count",
        "alt": "Sixteen counters shared equally between four rings, with no group counts given.",
        "title": null,
        "total": 16,
        "groups": 4,
        "layout": "rings",
        "show_count": "none",
        "unknown": true
      }
    },
    {
      "template": "practice",
      "heading": "Draw and share",
      "questions": [
        "Find half of 18 counters.",
        "Find a quarter of 8 counters.",
        "Find a quarter of 20 counters."
      ],
      "instruction": "Draw equal groups on your worksheet. Write each answer.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Plan the picnic",
      "questions": [
        "There are 20 grapes. Half go on a plate. How many?",
        "There are 20 grapes. A quarter go in a cup. How many?",
        "Stretch: The rest stay in the bowl. How many?"
      ],
      "instruction": "Use drawings to show where all 20 grapes go.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Show what you know",
      "questions": [
        "Draw a square. Split it into quarters. Shade one.",
        "Draw equal groups to find half of 10.",
        "Draw equal groups to find a quarter of 4."
      ],
      "instruction": "Work on your own on the worksheet.",
      "picture": null
    }
  ]
}
